    [17462] = {
        difficulty = "easy",
        difficultyReason = "Buy the inexpensive racial mount on a matching-race character; another race can instead earn the required city reputation.",
        acquisition = "1. Use a Horde character with Apprentice Riding. Undead can buy their racial skeletal mounts without an Exalted grind; other Horde races need Undercity Exalted.\n\n2. For the original Brill vendor location, speak to Zidormi east of Undercity in Tirisfal Glades (69.4, 62.8) and select the time before the Battle for Lordaeron if your zone is in the destroyed phase.\n\n3. If reputation is needed, buy and equip the Undercity Tabard from Captain Donald Adams beside the flight master in pre-battle Undercity (63.6, 48.8). Eligible Undead can skip to step 5.\n\n4. Clear Normal Botanica in Netherstorm (71.5, 55.5), with the tabard equipped, on a character able to solo it. Use the exit behind Warp Splinter, reset outside, and repeat until Undercity Exalted.\n\n5. Go to Zachariah Post's stables in pre-battle Brill (60.2, 52.4). Buy Red Skeletal Horse for 1 gold before discounts, then use the item to learn Red Skeletal Horse.",
        stepCount = 5,
        source = "Zachariah Post - Brill, pre-battle Tirisfal in Retail",
        tips = "This route deliberately uses Retail's pre-battle phase so the Brill pin matches the vendor. Green Skeletal Warhorse is a racial purchase; Red Skeletal Warhorse is the separate PvP reward.",
        requirements = "Horde; Apprentice Riding; Undead or Undercity Exalted",
        cost = "1 gold base; reputation discount applies",
        category = "Vendor",
        faction = "horde",
