    [5784] = {
        difficulty = "easy",
        difficultyReason = "Level an eligible Paladin or Warlock to the current learning level; the removed original mount quest chain is unnecessary.",
        acquisition = "1. Level a Warlock to at least 10. Any Warlock race or faction can unlock it.\n\n2. Open Collections > Mounts on that character, enable the Collected filter and search for Felsteed. Retail adds the class mount automatically as you level; drag it to an action bar to summon it.\n\n3. If it is hidden, clear the mount search and filters and check while logged into the eligible class. Other classes cannot ride it even if the account already owns it.\n\n4. The map pin is a class-trainer landmark for reference. The removed level-40/60 mount quest chains, Dire Maul ritual materials, and Scholomance event are not required in Retail.",
        stepCount = 4,
        source = "Automatic Warlock class-mount unlock",
        tips = "Class restriction remains after learning. The Codex of Xerrath changes this mount's fire color; green fire is optional.",
        requirements = "Warlock; level 10 or higher",
        cost = "No mount purchase",
        category = "Class",
        faction = "all",
        waypoints = {
            { mapID = 85, x = 0.482000, y = 0.454000, step = 4, label = "Class landmark only - automatic mount unlock, no trainer visit required" },
        },
    },
    [17229] = {
        difficulty = "medium",
        difficultyReason = "Raise a cub through 20 daily quest completions and provide the final turn-in materials; the reward is guaranteed after the time gate.",
        acquisition = "1. Use an Alliance character. Fast alternative during Classic Timewalking: visit Bobadormu at the Stormwind Embassy (56.0, 19.0), buy Commendation of the Wintersaber Trainers for 50 Timewarped Badges each, and use enough to reach Exalted. Each grants 500 reputation before bonuses; skip to step 6 when Exalted.\n\n2. Daily-quest alternative: find Rivern Frostwind on TOP of Frostsaber Rock in Winterspring (46.7, 17.7). Complete Get Them While They're Young by collecting eight Winterspring cubs around the rock, then return to him.\n\n3. Accept They Grow Up So Fast and keep the quest's Winterspring Cub item. Use it in Winterspring to summon the cub, then accept the daily quest from the cub itself.\n\n4. Complete the day's cub quest and turn it in to the cub for a Winterspring Cub Whisker. Keep doing the daily until you have 20 whiskers. Plan for 20 daily completions; missed days do not erase your whiskers. Realm-hopping shortcuts in old comments are unreliable.\n\n5. For the daily route, bring the 20 whiskers, 20 Rugged Leather, 20 Runecloth and 80 gold back to Rivern. Turn in They Grow Up So Fast to receive the reins.\n\n6. If you reached Wintersaber Trainers Exalted instead, open Rivern's vendor window and buy the reins for 80 gold; you can skip raising the cub. Use Reins of the Winterspring Frostsaber to learn the mount.",
        stepCount = 6,
        source = "Rivern Frostwind - Winterspring; Retail dailies or Exalted purchase",
        tips = "Buy and consume Wintersaber Trainers commendations on Alliance. Bobadormu is in the current capital Timewalking hub; old Tanaris anniversary directions describe the 2024 event. The cub used for quests is not the separately sold companion pet.",
        requirements = "Alliance; Apprentice Riding; daily quest or Wintersaber Trainers Exalted",
        cost = "Daily route: 20 Whiskers + 20 Rugged Leather + 20 Runecloth + 80 gold. Exalted vendor: 80 gold.",
        category = "Reputation",
        faction = "alliance",
        waypoints = {
            { mapID = 84, x = 0.560000, y = 0.190000, step = 1, label = "Bobadormu - Timewalking reputation shortcut" },
            { mapID = 83, x = 0.467000, y = 0.177000, step = 2, label = "Rivern Frostwind - on top of Frostsaber Rock" },
            { mapID = 83, x = 0.461000, y = 0.154000, step = 2, label = "Frostsaber Rock - cub collection area" },
            { mapID = 83, x = 0.467000, y = 0.177000, step = 5, label = "Rivern - daily-route turn-in" },
            { mapID = 83, x = 0.467000, y = 0.177000, step = 6, label = "Rivern - Exalted direct purchase" },
        },
    },
    [17481] = {
        difficulty = "hard",
        difficultyReason = "The final Stratholme boss has a low mount drop chance, so many repeat runs may be needed.",
        acquisition = "1. Set dungeon difficulty to Normal and enter Stratholme through the SERVICE ENTRANCE / Eastwall Gate in Eastern Plaguelands (43.3, 19.7). Check the dungeon map: you want Service Entrance / the Gauntlet. If it loads Main Gate, leave, reset all instances, then re-enter through the service gate.\n\n2. Kill Baroness Anastari, Nerub'enkan and Maleki the Pallid at the three ziggurats. After each boss, enter its ziggurat and kill every Thuzadin Acolyte inside. All three crystals must be disabled to open the way to Slaughter Square.\n\n3. Enter Slaughter Square and kill all the abominations. Kill Ramstein the Gorger when he emerges, then finish the undead wave and Black Guard Sentries so the Slaughterhouse opens.\n\n4. Kill Lord Aurius Rivendare inside and loot him for a chance at Deathcharger's Reins. The drop is random; kill order, crates and speed do not guarantee it. The old Baron name in comments refers to this same mount farm.\n\n5. If the reins did not drop, return outside the instance, choose Reset All Instances on your portrait and run it again. Pause at the hourly instance limit. Old Dreamwalk/follower-dungeon exit tricks have had graveyard bugs; walking out is the dependable route.\n\n6. When the reins drop, use them to learn Rivendare's Deathcharger. Either faction can learn and ride it.",
        stepCount = 6,
        source = "Lord Aurius Rivendare - Normal Stratholme, Service Entrance",
        tips = "Boss/ziggurat order does not alter the drop. Do not apply temporary Collector's Bounty drop rates to ordinary runs. The exterior entrance pin starts the route; no invented interior coordinates are supplied.",
        requirements = "Either faction; character capable of clearing Normal Stratholme",
        cost = "Random boss drop",
        category = "Dungeon and Raids",
        faction = "all",
        waypoints = {
            { mapID = 23, x = 0.433000, y = 0.197000, step = 1, label = "Stratholme Service Entrance / Eastwall Gate" },
        },
    },
    [13819] = {
        difficulty = "easy",
        difficultyReason = "Level an eligible Paladin or Warlock to the current learning level; the removed original mount quest chain is unnecessary.",
        acquisition = "1. Level an Alliance Paladin to at least 10. A Human Paladin is the straightforward unlock character for the horse model; other paladin races have their own racial class mounts.\n\n2. Open Collections > Mounts on that character, enable the Collected filter and search for Warhorse. Retail adds the class mount automatically as you level; drag it to an action bar to summon it.\n\n3. If it is hidden, clear the mount search and filters and check while logged into the eligible class. Other classes cannot ride it even if the account already owns it.\n\n4. The map pin is a class-trainer landmark for reference. The removed level-40/60 mount quest chains, Dire Maul ritual materials, and Scholomance event are not required in Retail.",
        stepCount = 4,
        source = "Automatic Alliance Paladin class-mount unlock",
        tips = "Class restriction remains after learning. Charger received an updated appearance in Midnight; old appearance comments do not mean its collection ID was retired.",
        requirements = "Alliance Paladin; level 10 or higher",
        cost = "No mount purchase",
        category = "Class",
        faction = "alliance",
        waypoints = {
            { mapID = 84, x = 0.387000, y = 0.329000, step = 4, label = "Class landmark only - automatic mount unlock, no trainer visit required" },
        },
    },
    [18989] = {
        difficulty = "easy",
        difficultyReason = "Buy the inexpensive racial mount on a matching-race character; another race can instead earn the required city reputation.",
        acquisition = "1. Use a Horde character with Apprentice Riding (Retail grants this at level 10). A Tauren can buy this racial mount without an Exalted grind; other races need Exalted with Thunder Bluff. If already eligible, skip to step 4.\n\n2. For the reputation route, buy and equip the Thunder Bluff Tabard from Brave Tuho beside the flight master in Thunder Bluff. Keep it equipped for the dungeon kills in step 3.\n\n3. On a character strong enough to solo it, enter The Botanica in Netherstorm on Normal difficulty (71.5, 55.5). Clear the enemies and bosses with the tabard equipped, use the exit behind Warp Splinter, reset outside and repeat until Thunder Bluff is Exalted. Wait if you hit the hourly instance limit.\n\n4. Visit Harb Clawhoof in Mulgore, Bloodhoof Village (47.6, 58.8). Buy Gray Kodo; its base price is 1 gold, reduced by reputation discounts.\n\n5. Use Gray Kodo from your bags to learn Gray Kodo. Open Collections > Mounts and search for Gray Kodo; it is shared with eligible Horde characters on your account.",
        stepCount = 5,
        source = "Harb Clawhoof - Mulgore, Bloodhoof Village",
        tips = "The matching original race skips the reputation route. Allied races are separate races; use the vendor's eligibility check. Swift and ordinary versions now scale with riding skill.",
        requirements = "Horde; Apprentice Riding; matching original race or Thunder Bluff Exalted",
        cost = "1 gold base; reputation discount applies",
        category = "Vendor",
        faction = "horde",
        waypoints = {
            { mapID = 88, x = 0.466000, y = 0.500000, step = 2, label = "Brave Tuho - optional reputation tabard" },
            { mapID = 109, x = 0.715000, y = 0.555000, step = 3, label = "The Botanica - optional Normal reputation runs" },
            { mapID = 7, x = 0.476000, y = 0.588000, step = 4, label = "Harb Clawhoof - Gray Kodo" },
        },
    },
