    [22717] = {
        difficulty = "medium",
        difficultyReason = "Earn 15 Marks of Honor and buy the faction mount; the original PvP rank and reputation requirements are no longer needed.",
        acquisition = "1. Use an eligible Alliance character and gather 15 Mark of Honor items. These are the account-bound items awarded by PvP reward boxes, not your Honor currency total or old battleground-specific tokens.\n\n2. Earn Marks through battleground PvP rewards. At the current PvP vendor, you can also exchange 2,000 Honor for an Orboreal Distinguishment containing 5 Marks, if offered; three boxes provide the 15 Marks for one mount. Transfer your Marks to the buyer before traveling.\n\n3. Visit Lieutenant Karter in Stormwind, outside the Champion's Hall in Old Town (76.4, 65.2). Buy Black War Steed Bridle for 15 Marks of Honor. No city Exalted reputation, old PvP rank, or Alterac Valley reputation grind is required.\n\n4. Use Black War Steed Bridle to learn Black War Steed. Search Collections > Mounts to confirm it was added. The purchase unlock is account-wide for characters eligible to use the mount.",
        stepCount = 4,
        source = "Lieutenant Karter - Stormwind, outside the Champion's Hall in Old Town",
        tips = "The price is 15 Mark of Honor items. Comments quoting 2,000 Honor, 50 AV tokens, 30 of each battleground token, or Rank 11 describe old systems.",
        requirements = "Alliance; Apprentice Riding; 15 Mark of Honor",
        cost = "15 Mark of Honor",
        category = "PvP",
        faction = "alliance",
        waypoints = {
            { mapID = 84, x = 0.764000, y = 0.652000, step = 3, label = "Lieutenant Karter - Black War Steed Bridle" },
        },
    },
