    [23219] = {
        difficulty = "easy",
        difficultyReason = "Buy the inexpensive racial mount on a matching-race character; another race can instead earn the required city reputation.",
        acquisition = "1. Use an Alliance character with Apprentice Riding. Night Elves can buy their racial sabers without Exalted; other races need Darnassus Exalted.\n\n2. If Teldrassil is burned in your phase, speak to Zidormi in Darkshore (48.9, 24.5) and ask to see it before the burning. Travel to the restored Darnassus; this is a past phase in Retail.\n\n3. If you still need reputation, buy the Darnassus Tabard from Moon Priestess Lasara beside the portal in old Darnassus (36.6, 49.0). Equip it for step 4; eligible Night Elves can skip to step 5.\n\n4. Enter Normal Botanica in Netherstorm (71.5, 55.5) on a character able to solo it. Kill the enemies and bosses with the tabard equipped, take the exit behind Warp Splinter, reset outside and repeat until Darnassus Exalted.\n\n5. Buy Reins of the Swift Mistsaber from Lelanai in Darnassus's Cenarion Enclave (42.6, 33.0). The base price is 10 gold, before reputation discounts.\n\n6. Use the item in your bags to learn Swift Mistsaber, then find it under Collections > Mounts. You can return to the present by speaking to Zidormi again.",
        stepCount = 6,
        source = "Lelanai - Darnassus (Retail pre-burning phase)",
        tips = "The old mount vendor remains accessible in Retail through Zidormi. Visit Lelanai in Darnassus, not the unrelated Amirdrassil renown vendor.",
        requirements = "Alliance; Apprentice Riding; Night Elf or Darnassus Exalted",
        cost = "10 gold base; reputation discount applies",
        category = "Vendor",
