-- Give entries and details the same reviewed view without changing identities.
for _, guide in pairs(TDP.CollectionWalkthroughs.mounts) do
    guide.availabilityReviewedAt = "2026-11-04"
    guide.acquisition = "Difficulty: " .. guide.difficulty:gsub("^%l", string.upper) .. " - " .. guide.difficultyReason .. "\n\n" .. guide.acquisition
end
local fields = { 'acquisition', 'source', 'tips', 'requirements', 'cost', 'category', 'waypoints', 'faction', 'difficulty', 'difficultyReason', 'availabilityReviewedAt' }
for patchKey, patch in pairs(TDP.PatchCatalog.patches) do
    if patchKey:match('^1%.') then
        for _, entry in ipairs(patch.mounts) do
            local guide = TDP.CollectionWalkthroughs.mounts[entry.spellId]
            if guide then
                local original = TDP.PatchCatalog.mountDetails[patchKey][entry.name] or {}
                local details = {}
                for key, value in pairs(original) do details[key] = value end
                for _, field in ipairs(fields) do
                    entry[field], details[field] = guide[field], guide[field]
                end
                details.sourceType = guide.category
                TDP.PatchCatalog.mountDetails[patchKey][entry.name] = details
            end
        end
    end
end
